#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MOD = 1000000007;
const int MAXN = 8;
const int MAXSZ = 1048576 + 5;

inline int add(int a, int b) { return (a + b >= MOD) ? (a + b - MOD) : (a + b); }
inline int sub(int a, int b) { return (a >= b) ? (a - b) : (a + MOD - b); }
inline int mul(int a, int b) { return (ll)a * b % MOD; }

inline void addto(int &x, int y) { x = add(x, y); }

inline int modpow(int base, int exp) {
    int res = 1;
    while (exp) {
        if (exp & 1) res = mul(res, base);
        base = mul(base, base);
        exp >>= 1;
    }
    return res;
}

int n, prob[MAXN][MAXN], match[MAXN][MAXN], permMask[7][7][7], fullMask, answer;
int dpTable[MAXSZ];

inline bool matches(int x, int y, int z) {
    int arr[4] = {0, x, y, z};
    int idx[4] = {0, 1, 2, 3};
    do {
        bool ok = true;
        for (int i = 1; i <= 3; ++i) {
            if (!match[idx[i]][arr[i]]) { ok = false; break; }
        }
        if (ok) return true;
    } while (next_permutation(idx + 1, idx + 4));
    return false;
}

void dfsForward(int curVal, int row, int col) {
    bool used[7] = {false, true, true, true, true, true, true};
    if (!curVal) return;
    if (row == 4) {
        for (int i = 1; i <= 6; ++i) used[i] = true;
        int state = 0;
        for (int i = 1; i <= 6; ++i) {
            for (int j = i + 1; j <= 6; ++j) {
                for (int k = j + 1; k <= 6; ++k) {
                    if (matches(i, j, k)) {
                        int a = -1, b = -1, c = -1;
                        used[i] = used[j] = used[k] = false;
                        for (int l = 1; l <= 6; ++l) {
                            if (!used[l]) {
                                if (a == -1) a = l;
                                else if (b == -1) b = l;
                                else c = l;
                            }
                        }
                        used[i] = used[j] = used[k] = true;
                        if (c != -1) state |= permMask[a][b][c];
                    }
                }
            }
        }
        addto(dpTable[state], curVal);
        return;
    }
    match[row][col] = 1;
    int nextVal = mul(curVal, prob[row][col]);
    if (col == 6) dfsForward(nextVal, row + 1, 1);
    else dfsForward(nextVal, row, col + 1);
    match[row][col] = 0;
    nextVal = mul(curVal, sub(1, prob[row][col]));
    if (col == 6) dfsForward(nextVal, row + 1, 1);
    else dfsForward(nextVal, row, col + 1);
}

void dfsBackward(int curVal, int row, int col) {
    if (!curVal) return;
    if (row == 7) {
        int state = 0;
        for (int i = 1; i <= 6; ++i) {
            for (int j = i + 1; j <= 6; ++j) {
                for (int k = j + 1; k <= 6; ++k) {
                    if (matches(i, j, k)) state |= permMask[i][j][k];
                }
            }
        }
        addto(answer, mul(curVal, dpTable[fullMask ^ state]));
        return;
    }
    match[row - 3][col] = 1;
    int nextVal = mul(curVal, prob[row][col]);
    if (col == 6) dfsBackward(nextVal, row + 1, 1);
    else dfsBackward(nextVal, row, col + 1);
    match[row - 3][col] = 0;
    nextVal = mul(curVal, sub(1, prob[row][col]));
    if (col == 6) dfsBackward(nextVal, row + 1, 1);
    else dfsBackward(nextVal, row, col + 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    int inv100 = modpow(100, MOD - 2);
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            int x; cin >> x;
            prob[i][j] = mul(x, inv100);
        }
    }
    for (int i = n + 1; i <= 6; ++i) prob[i][i] = 1;
    int cnt = 0;
    for (int i = 1; i <= 6; ++i) {
        for (int j = i + 1; j <= 6; ++j) {
            for (int k = j + 1; k <= 6; ++k) {
                permMask[i][j][k] = 1 << cnt;
                ++cnt;
            }
        }
    }
    fullMask = (1 << cnt) - 1;
    dfsForward(1, 1, 1);
    for (int j = 0; j < cnt; ++j) {
        for (int i = 0; i < (1 << cnt); ++i) {
            if (i & (1 << j)) addto(dpTable[i], dpTable[i ^ (1 << j)]);
        }
    }
    answer = 0;
    dfsBackward(1, 4, 1);
    answer = sub(1, answer);
    cout << answer << '\n';
    return 0;
}
